import { BrowserRouter as Router, Route, Routes, Navigate, Outlet } from "react-router-dom";
import './SignUp/SignUp.css';
import './LogIn/logIn.css';
import './HomePage/HomePage.css';
import { useState } from 'react';
import SignUp from './SignUp/SignUp.js';
import LogIn from './LogIn/logIn.js';
import HomePage from './HomePage/HomePage.js';
import ProfilePage from "./Profile/ProfilePage";






function App() {
  const [activeUser, setActiveUser] = useState('');
  // const Layout = () => {
  //   return(<ThemeContext.Provider value={{theme, changeTheme}}>
  //     <div className="container- fluid" id={theme}>
  //         <div className="row upfeed">
  //           <UpMenu activeUser={activeUser} changeTheme = {changeTheme}/>
  //         </div>
  //         <div className="row feed">
  //             <div className="col-3">
  //                 <LeftMenu activeUser={activeUser} />

  //             </div>
  //             <div className="row col-6">
  //               <Outlet/>
  //             </div>
  //             <div className="col-3">
  //                 <RightMenu />
  //             </div>
  //         </div>
  //     </div>
  //     </ThemeContext.Provider>)
  // }

  
  return (
    <div className="App">
      <header className="App-header">
        <Router>
          <Routes>
            {/* if(activeUser === ''){
             <Route path="" element={<LogIn setActiveUser={setActiveUser}  />} /> 
            } 
             else {
              <Route path="/HomePage" element={ <HomePage activeUser={activeUser}  />} />
            }  */}
            
             <Route path="" element={<LogIn setActiveUser={setActiveUser} />} /> 

             {/* <Route path="" element={!activeUser ? <LogIn setActiveUser={setActiveUser} /> : <HomePage activeUser={activeUser}/>} />  */}


            {/* <Route path="/HomePage"
              element={
                activeUser.token === "" ? (
                  <LogIn setActiveUser={setActiveUser} />
                ) : (<HomePage activeUser={activeUser} />
                )
              } /> */}

            
            <Route path="/SignUp" element={<SignUp />} />
            <Route path="/HomePage" element={activeUser ? <HomePage activeUser={activeUser} setActiveUser={setActiveUser} /> : <Navigate to="/ " />} />
            <Route path="/Profile/:email/:correnttheme" element={<ProfilePage activeUser={activeUser} setActiveUser={setActiveUser} />} />
          </Routes>
        </Router>
      </header>
    </div>
  );
}

export default App;
